export function detectPalmarLines(payload) {
    const custom = payload.customLineMetrics || {};
    const lifeLine = {
        id: 'life_line',
        nameEn: 'Life Line',
        nameCn: '生命線',
        nameSanskrit: 'Pitru / Aayu Rekha (आयु रेखा)',
        detected: true,
        clarity: custom.lifeLine?.clarity || 'DEEP_CLEAR',
        lengthPercentage: custom.lifeLine?.lengthPercentage ?? 85,
        depthScore: custom.lifeLine?.depthScore ?? 88,
        curvature: custom.lifeLine?.curvature || 'STEEP_ARC',
        startRegion: 'Radial Edge (Jupiter / Thumb Interval)',
        endRegion: 'Lower Palm Base near Wrist',
        hasForkAtEnd: custom.lifeLine?.hasForkAtEnd ?? true,
        islandsCount: custom.lifeLine?.islandsCount ?? 0,
        breaksCount: custom.lifeLine?.breaksCount ?? 0,
        branchesUpwardCount: custom.lifeLine?.branchesUpwardCount ?? 2,
        branchesDownwardCount: custom.lifeLine?.branchesDownwardCount ?? 1,
        keyObservation: 'Deep, unbroken arc sweeping broadly around Shukra Mount; indicates robust physical constitution and high vitality baseline.',
    };
    const headLine = {
        id: 'head_line',
        nameEn: 'Head Line',
        nameCn: '智慧線',
        nameSanskrit: 'Matri / Masti Rekha (मस्तिष्क रेखा)',
        detected: true,
        clarity: custom.headLine?.clarity || 'DEEP_CLEAR',
        lengthPercentage: custom.headLine?.lengthPercentage ?? 82,
        depthScore: custom.headLine?.depthScore ?? 85,
        curvature: custom.headLine?.curvature || 'SLOPING_DOWN',
        startRegion: 'Jupiter Mount Margin',
        endRegion: 'Upper Moon Mount (Chandra)',
        hasForkAtEnd: custom.headLine?.hasForkAtEnd ?? true, // Writer's Fork
        islandsCount: custom.headLine?.islandsCount ?? 0,
        breaksCount: custom.headLine?.breaksCount ?? 0,
        branchesUpwardCount: custom.headLine?.branchesUpwardCount ?? 1,
        branchesDownwardCount: custom.headLine?.branchesDownwardCount ?? 0,
        keyObservation: 'Long, deep line terminating in a distinct dual fork (Writer’s Fork); balances analytical rigor with creative synthesis.',
    };
    const heartLine = {
        id: 'heart_line',
        nameEn: 'Heart Line',
        nameCn: '感情線',
        nameSanskrit: 'Ayu / Hridaya Rekha (हृदय रेखा)',
        detected: true,
        clarity: custom.heartLine?.clarity || 'DEEP_CLEAR',
        lengthPercentage: custom.heartLine?.lengthPercentage ?? 88,
        depthScore: custom.heartLine?.depthScore ?? 84,
        curvature: custom.heartLine?.curvature || 'GENTLE_CURVE',
        startRegion: 'Ulnar Margin under Mercury',
        endRegion: 'Jupiter / Saturn Inter-Mount Apex',
        hasForkAtEnd: custom.heartLine?.hasForkAtEnd ?? true,
        islandsCount: custom.heartLine?.islandsCount ?? 0,
        breaksCount: custom.heartLine?.breaksCount ?? 0,
        branchesUpwardCount: custom.heartLine?.branchesUpwardCount ?? 3,
        branchesDownwardCount: custom.heartLine?.branchesDownwardCount ?? 0,
        keyObservation: 'Unbroken curve terminating in a balanced trident under Jupiter Mount; indicates emotional loyalty, dignity, and warmth.',
    };
    const fateLine = {
        id: 'fate_line',
        nameEn: 'Fate / Destiny Line',
        nameCn: '事業線',
        nameSanskrit: 'Bhagya Rekha (भाग्य रेखा)',
        detected: custom.fateLine?.detected ?? true,
        clarity: custom.fateLine?.clarity || 'MODERATE',
        lengthPercentage: custom.fateLine?.lengthPercentage ?? 75,
        depthScore: custom.fateLine?.depthScore ?? 78,
        curvature: custom.fateLine?.curvature || 'STRAIGHT',
        startRegion: 'Upper Wrist Plain / Moon Mount',
        endRegion: 'Saturn Mount Base',
        hasForkAtEnd: custom.fateLine?.hasForkAtEnd ?? false,
        islandsCount: custom.fateLine?.islandsCount ?? 0,
        breaksCount: custom.fateLine?.breaksCount ?? 0,
        branchesUpwardCount: custom.fateLine?.branchesUpwardCount ?? 2,
        branchesDownwardCount: custom.fateLine?.branchesDownwardCount ?? 0,
        keyObservation: 'Strong vertical shaft ascending to Saturn Mount; indicates self-made destiny, strong purpose, and career continuity.',
    };
    const sunLine = {
        id: 'sun_line',
        nameEn: 'Sun / Apollo Line',
        nameCn: '太陽線',
        nameSanskrit: 'Surya Rekha (सूर्य रेखा)',
        detected: custom.sunLine?.detected ?? true,
        clarity: custom.sunLine?.clarity || 'MODERATE',
        lengthPercentage: custom.sunLine?.lengthPercentage ?? 45,
        depthScore: custom.sunLine?.depthScore ?? 70,
        curvature: custom.sunLine?.curvature || 'STRAIGHT',
        startRegion: 'Plain of Mars / Head Line',
        endRegion: 'Sun Mount Apex',
        hasForkAtEnd: custom.sunLine?.hasForkAtEnd ?? false,
        islandsCount: custom.sunLine?.islandsCount ?? 0,
        breaksCount: custom.sunLine?.breaksCount ?? 0,
        branchesUpwardCount: custom.sunLine?.branchesUpwardCount ?? 1,
        branchesDownwardCount: custom.sunLine?.branchesDownwardCount ?? 0,
        keyObservation: 'Clear line rising to Sun Mount; indicates artistic reputation, executive prestige, and public recognition.',
    };
    const mercuryLine = {
        id: 'mercury_line',
        nameEn: 'Mercury / Health Line',
        nameCn: '健康線',
        nameSanskrit: 'Budh / Health Rekha (बुध रेखा)',
        detected: custom.mercuryLine?.detected ?? true,
        clarity: custom.mercuryLine?.clarity || 'FAINT',
        lengthPercentage: custom.mercuryLine?.lengthPercentage ?? 40,
        depthScore: custom.mercuryLine?.depthScore ?? 65,
        curvature: custom.mercuryLine?.curvature || 'STRAIGHT',
        startRegion: 'Life Line Margin',
        endRegion: 'Mercury Mount Base',
        hasForkAtEnd: false,
        islandsCount: 0,
        breaksCount: 0,
        branchesUpwardCount: 1,
        branchesDownwardCount: 0,
        keyObservation: 'Faint line ascending towards Mercury Mount; indicates commercial intellect and active digestive fire (Agni).',
    };
    return {
        lifeLine,
        headLine,
        heartLine,
        fateLine,
        sunLine,
        mercuryLine,
    };
}
